function toggleFieldsBasedOnIsGroup(frm) {
    const isGroup = frm.doc.is_group;

    // Replace 'your_fieldname' with the actual field you want to hide
    frm.toggle_display("expected_time", !isGroup);
    frm.toggle_display("custom_الأولوية_الاستراتيجية", !isGroup);
    frm.toggle_display("custom_القيمة_المضافة", !isGroup);
    frm.toggle_display("custom_التأثير_على_الجودة", !isGroup);
    frm.toggle_display("custom___التعقيد_الفني", !isGroup);}

function calculateScaledValue(value, maxValue, maxOutput) {
    const clampedValue = Math.max(0, Math.min(maxValue, value));
    const scaled = (clampedValue / maxValue) * maxOutput;
    return Math.round(scaled);
}


function calculateTaskWeight(frm) {
    if (!frm.doc) return;

    // Custom field values
    const priorityMap = {'0': 0, '1': 4, '2': 8, '3': 12, '4': 16, '5': 20};
    const comlexityMap = {'0': 0, '1': 8, '2': 16, '3': 24, '4': 32, '5': 40};
    const stratigicPriorityMap = {'0': 0, '1': 4, '2': 8, '3': 12, '4': 16, '5': 20};
    const qualityMap = {'0': 0, '1': 2, '2': 4, '3': 6, '4': 8, '5': 10};
    const addedValueMap = {'0': 0, '1': 2, '2': 4, '3': 6, '4': 8, '5': 10};

    // Check if it's a group task
    if (frm.doc.is_group && frm.doc.depends_on) {
        let totalDependentWeight = 0;
        let count = 0;
        if(frm.doc.depends_on.length > 0){
        // Loop through dependencies and fetch their weight
        frm.doc.depends_on.forEach((row) => {
            frappe.db.get_value("Task", row.task, "task_weight", null, true).then((res) => {
                const weight = res.message?.task_weight || 0;
                totalDependentWeight += weight;
                count += 1;

        // Once all are fetched, update this task's weight
        if (count === frm.doc.depends_on.length) {
            const averageWeight = totalDependentWeight / count;

        console.log("totalDependentWeight="+totalDependentWeight);
        console.log("averageWeight="+averageWeight);
        console.log("count="+count);
            frappe.model.set_value(frm.doctype, frm.docname, 'task_weight', averageWeight);
            frm.refresh_field('task_weight');
        }
                
            });
        });

        }else{
            frappe.model.set_value(frm.doctype, frm.docname, 'task_weight', 0);
            frm.refresh_field('task_weight');

        }

    } else {
        // Normal weight calculation for non-group tasks
        const comlexityValue = comlexityMap[frm.doc.custom___التعقيد_الفني] || 0;
        const expectedTimeValue = calculateScaledValue(frm.doc.expected_time, 14, 20);
        const priorityValue = priorityMap[frm.doc.custom_الأولوية_الاستراتيجية] || 0;
        const addedValue = addedValueMap[frm.doc.custom_القيمة_المضافة] || 0;
        const qualityValue = qualityMap[frm.doc.custom_التأثير_على_الجودة] || 0;

        const weight = priorityValue + comlexityValue + expectedTimeValue + qualityValue + addedValue;

        frappe.model.set_value(frm.doctype, frm.docname, 'task_weight', weight);
        frm.refresh_field('task_weight');
    }
}

