function lock_clearance_rows(frm) {
  const grid = frm.get_field('clearance_lines').grid;

  // Hide add row buttons
  grid.wrapper.find('.grid-add-row, .grid-add-multiple-rows').hide();

  // Wait until grid is fully rendered
  setTimeout(() => {
    (grid.grid_rows || []).forEach(gr => {
      const d = gr.doc;
      const is_owner = d.approver_user && d.approver_user === frappe.session.user;

      // Lock/unlock inline editing
      gr.toggle_editable(!!is_owner);

      // Prevent opening row form for non-owners
      if (!is_owner) {
        $(gr.row).find('.btn-open-row, .grid-row-open, .btn-edit').hide();
      }
    });
  }, 300);
}

frappe.ui.form.on('Clearance', {

  onload(frm) {
    // filter "case" link field based on selected employee
    frm.set_query("case", function () {
      return {
        filters: {
          employee: frm.doc.employee || ""
        }
      };
    });
  },

  refresh(frm) {
    lock_clearance_rows(frm);
  },

  employee(frm) {
    if (!frm.doc.employee) return;

    frm.set_value("case", null);
    frm.refresh_field("case");
    frm.clear_table("clearance_lines");
    frm.refresh_field("clearance_lines");

    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Clearance Approval Settings",
        filters: {},
        fields: [
          "unit_type",
          "unit_name",
          "approver_user",
          "responsible_name",
          "department",
          "office",
          "section"
        ],
        limit_page_length: 999
      },
      callback: function (r) {

        if (!r.message || r.message.length === 0) {
          frappe.msgprint(__("No Clearance Approval Settings found."));
          return;
        }

        r.message.forEach(setting => {

          let row = frm.add_child("clearance_lines");

          row.unit_type = setting.unit_type;
          row.unit_name = setting.unit_name;
          row.department = setting.department;
          row.office = setting.office;
          row.section = setting.section;
          row.approver_user = setting.approver_user;
          row.responsible_employee = setting.responsible_name;

          // Default status
          row.clearance_status = __("Pending");
        });

        frm.refresh_field("clearance_lines");
        lock_clearance_rows(frm);
      }
    });
  }
});

