/**
 * Enhanced Media Editor integration for attachments in specific doctypes
 * Doctypes: Internal Request, A, B
 */

async function get_user_credentials() {
    try {
        const user = frappe.session.user;
        const { message } = await frappe.db.get_value('User', user, ['stamp', 'signature']);
        return {
            stamp: message?.stamp || '',
            sign: message?.signature || ''
        };
    } catch (error) {
        console.error('Failed to fetch user credentials:', error);
        return { stamp: '', sign: '' };
    }
}

function extract_filename_from_href(href) {
    try {
        if (!href) return null;
        const url = new URL(href, window.location.origin);

        if (url.pathname.startsWith('/files/')) {
            return url.pathname.split('/').pop();
        }

        if (url.pathname.includes('/api/method/frappe.utils.file_manager.download_file')) {
            const param = url.searchParams.get('file_url');
            return param ? param.split('/').pop() : null;
        }

        return href.split('/').pop().split('?')[0];
    } catch {
        return null;
    }
}

async function open_in_media_editor(filename, stamp, sign) {
    const link = `/media-editor/?path=${encodeURIComponent(filename)}&stamp=${encodeURIComponent(stamp)}&sign=${encodeURIComponent(sign)}`;
    window.open(link, '_blank', 'noopener');
}

function render_media_links(frm) {
    const htmlField = frm.get_field('media_links');
    if (!htmlField) return;

    const attachments = frm.attachments?.get_attachments?.() || [];
    const publicFiles = attachments.filter(f => !f.is_private);

    const listItems = publicFiles.map(f => {
        const name = (f.file_url || '').split('/').pop();
        const label = frappe.utils.escape_html(f.file_name || name);
        return `<li style="margin:4px 0">
      <a href="#" class="media-link" data-filename="${encodeURIComponent(name)}">${label}</a>
    </li>`;
    });

    const html = listItems.length
        ? `<div><strong>Open in Media Editor</strong><ul style="padding-left:18px; list-style:disc">${listItems.join('')}</ul></div>`
        : `<div class="text-muted">No public attachments.</div>`;

    htmlField.$wrapper.html(html);

    // Bind custom click handler
    htmlField.$wrapper.find('.media-link').on('click', async function (e) {
        e.preventDefault();
        if (!filename || !(stamp || sign)) return;
        const filename = decodeURIComponent(this.dataset.filename);
        await open_in_media_editor(filename, stamp, sign);
    });
}

function bind_sidebar_redirect(frm) {
    if (frm._bound_media_redirect) return;
    frm._bound_media_redirect = true;

    frm.$wrapper.on('click', '.form-sidebar .form-attachments a, .form-sidebar .attachments a', async function (e) {
        const href = this.getAttribute('href');
        if (!href || href.includes('/private/files/') || href.includes('download_file')) return;

        const filename = extract_filename_from_href(href);
        const { stamp, sign } = await get_user_credentials();
        if (!filename || !(stamp || sign)) return;

        e.preventDefault();
        await open_in_media_editor(filename, stamp, sign);
    });
}

