// ==== Utility Functions (unchanged) ====
function loadSheetJS(callback) {
    if (window.XLSX) return callback();
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
    script.onload = callback;
    script.onerror = () => frappe.msgprint(__('Failed to load Excel library'));
    document.head.appendChild(script);
}

function loadJSZipAndFileSaver(callback) {
    if (window.JSZip && window.saveAs) return callback();
    loadScript('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js', () =>
        loadScript('https://cdnjs.cloudflare.com/ajax/libs/FileSaver.js/2.0.5/FileSaver.min.js', callback)
    );
}

function loadScript(src, callback) {
    const script = document.createElement('script');
    script.src = src;
    script.onload = callback;
    script.onerror = () => frappe.throw(__('Failed to load: ') + src);
    document.head.appendChild(script);
}

