// Helper: compute and set both visitor_qr_code and barcode
function generate_qr_code(frm) {
    if (frm.doc.document_number && frm.doc.nationality) {
        const cleanDocNumber = (frm.doc.document_number || '').toString().trim();
        const cleanNationality = (frm.doc.nationality || '').toString().trim();

        if (!cleanDocNumber || !cleanNationality) {
            set_barcode_fields(frm, '');
            return;
        }

        const expected_value = cleanDocNumber + "-" + cleanNationality;

        if (frm.doc.visitor_qr_code !== expected_value || frm.doc.barcode !== expected_value) {
            set_barcode_fields(frm, expected_value);
        }
    } else {
        set_barcode_fields(frm, '');
    }
}

// Helper to update both fields consistently
function set_barcode_fields(frm, value) {
    frappe.run_serially([
        () => frm.set_value('visitor_qr_code', value),
        () => frm.set_value('barcode', value)
    ]);
}

