// --------------------------
// Language / RTL helpers
// --------------------------
function get_lang() {
  return (frappe.boot && frappe.boot.lang) || frappe.lang || "en";
}
function is_arabic() {
  return (get_lang() || "").toLowerCase().startsWith("ar");
}
function get_dir() {
  return is_arabic() ? "rtl" : "ltr";
}

// --------------------------
// TAB ACTIVATION (reliable)
// --------------------------
function activate_tab(frm, tab_fieldname) {
  const f = frm.get_field(tab_fieldname);
  if (f && f.$tab && f.$tab.length) {
    f.$tab.trigger("click");
    return;
  }

  const $li = frm.$wrapper.find(`li[data-fieldname="${tab_fieldname}"]`);
  if ($li.length) {
    $li.trigger("click");
    return;
  }

  const $a = frm.$wrapper.find(`a[data-fieldname="${tab_fieldname}"]`);
  if ($a.length) $a.trigger("click");
}

// --------------------------
// CASE TYPE HELPER
// --------------------------
function is_resignation_case(frm) {
  return (frm.doc.case_type || "").trim() === "Resignation";
}

// =========================
// THEME COLORS PER DOCTYPE (visual theme only)
// =========================
const SEP_THEME = {
  "Resignation Request": {
    // Teal (مثل الدائرة اليسار)
    badge_bg: "#E6FCF5",
    badge_color: "#0B7285",
    card_border: "#0B7285",
    btn_class: "btn-primary"
  },
  "Exit Interview Minutes": {
    // Green (مثل Done)
    badge_bg: "#EBFBEE",
    badge_color: "#2F9E44",
    card_border: "#2F9E44",
    btn_class: "btn-success"
  },
  "Clearance": {
    // Gold / Amber (مثل Pending Review)
    badge_bg: "#FFF9DB",
    badge_color: "#F59F00",
    card_border: "#F59F00",
    btn_class: "btn-warning"
  },
  "Final Dues Statement": {
    // Red accent (للخطوات الحساسة/المتأخرة)
    badge_bg: "#FFF5F5",
    badge_color: "#C92A2A",
    card_border: "#C92A2A",
    btn_class: "btn-danger"
  }
};

// =========================
// MAIN BUILDER
// =========================
async function build_separation_dashboard(frm) {
  if (!frm.fields_dict.dashboard_html || !frm.fields_dict.dashboard_html.$wrapper) return;

  const dir = get_dir();

  if (frm.is_new()) {
    frm.fields_dict.dashboard_html.$wrapper.html(
      `<div dir="${dir}" class="text-muted">${__("Save the case to enable dashboard actions.")}</div>`
    );
    return;
  }

  const show_hr05 = is_resignation_case(frm);

  // Fetch linked docs by same case
  const hr05 = await get_doc_status_by_case("Resignation Request", frm.doc.name);
  const hr07 = await get_doc_status_by_case("Exit Interview Minutes", frm.doc.name);
  const hr08 = await get_doc_status_by_case("Clearance", frm.doc.name);
  const hr09 = await get_doc_status_by_case("Final Dues Statement", frm.doc.name);

  // Fetch employee brief (including image)
  const emp = await get_employee_brief(frm.doc.employee);

  // Next action logic (case-type aware)
  const next = get_next_action(frm, { hr05, hr07, hr08, hr09 });

  // Next theme (optional coloring)
  const nextTheme = {
    HR05: SEP_THEME["Resignation Request"],
    HR07: SEP_THEME["Exit Interview Minutes"],
    HR08: SEP_THEME["Clearance"],
    HR09: SEP_THEME["Final Dues Statement"]
  }[next.action] || {};

  const nextBg = nextTheme.badge_bg || "#e7f5ff";
  const nextColor = nextTheme.badge_color || "#1864ab";
  const nextBorder = nextTheme.card_border || "#cfe2ff";
  const nextBtnClass = nextTheme.btn_class || "btn-primary";

  // Cards HTML (HR05 only if resignation)
  const cards_html = `
    <div class="row" style="gap:12px; margin:0;">
      ${show_hr05 ? dash_card(__("HR05 Resignation Request"), hr05, "Resignation Request") : ""}
      ${dash_card(__("HR07 Exit Interview"), hr07, "Exit Interview Minutes")}
      ${dash_card(__("HR08 Clearance"), hr08, "Clearance")}
      ${dash_card(__("HR09 Final Dues"), hr09, "Final Dues Statement")}
    </div>
  `;

  // Render HTML
  const html = `
    <div dir="${dir}">
      <style>
        .esc-alert { border-radius:12px; margin:0; }
        .esc-alert-head { display:flex; justify-content:space-between; align-items:center; gap:10px; }
        .esc-alert-text { min-width:0; }
        .esc-alert-text b { font-weight:800; }
        .esc-next-btn { border-radius:10px; white-space:nowrap; }
      </style>

      <div style="margin-bottom:12px;">
        <div class="alert esc-alert" style="background:${nextBg}; color:${nextColor}; border:1px solid ${nextBorder};">
          <div class="esc-alert-head">
            <div class="esc-alert-text">
              <b>${__("Next Action")}:</b> ${frappe.utils.escape_html(next.label)}
            </div>

           ${(next.action !== "DONE" && next.action !== "NONE") ? `
              <button type="button" class="btn btn-sm ${nextBtnClass} esc-next-btn dash-next-btn" data-action="${next.action}">
                ${__("Go")}
              </button>` : ""
            }
          </div>
        </div>
      </div>

      ${cards_html}

      ${info_grid(frm, emp)}
    </div>
  `;

  frm.fields_dict.dashboard_html.$wrapper.html(html);

  // Card buttons -> Open/Create
  frm.fields_dict.dashboard_html.$wrapper
    .find(".dash-btn")
    .off("click")
    .on("click", function () {
      open_or_create_by_case(frm, $(this).data("doctype"));
    });

  // Next action button
  frm.fields_dict.dashboard_html.$wrapper
    .find(".dash-next-btn")
    .off("click")
    .on("click", function () {
      const action = $(this).data("action");
      if (action === "HR05") open_or_create_by_case(frm, "Resignation Request");
      if (action === "HR07") open_or_create_by_case(frm, "Exit Interview Minutes");
      if (action === "HR08") open_or_create_by_case(frm, "Clearance");
      if (action === "HR09") open_or_create_by_case(frm, "Final Dues Statement");
      if (action === "ISSUE") {
          // يفتح نفس الكيس، والمستخدم ينفذ الـ workflow action من الأعلى
          // أو تقدر لاحقًا تربطه بزر API لتطبيق transition تلقائيًا
          frappe.show_alert({ message: __("Use 'Issue Statement' workflow action to issue the statement."), indicator: "blue" });
       }
    });
}

// =========================
// UI COMPONENTS
// =========================
function dash_card(title, info, doctype) {
  const status = info.exists ? (info.state || __("Unknown")) : __("Not Started");
  const btnText = info.exists ? __("Open") : __("Create");

  const t = SEP_THEME[doctype] || {};
  const badgeBg = t.badge_bg || "#f1f3f5";
  const badgeColor = t.badge_color || "#333";
  const borderColor = t.card_border || "#dee2e6";
  const btnClass = t.btn_class || "btn-dark";

  return `
    <div class="col" style="min-width:260px; padding:0;">
      <div class="card" style="padding:14px; border-radius:14px; border:1px solid ${borderColor};">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; gap:10px;">
          <div style="font-weight:800; min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
            ${frappe.utils.escape_html(title)}
          </div>
          <span class="badge" style="
              padding:6px 10px;
              border-radius:999px;
              background:${badgeBg};
              color:${badgeColor};
              font-weight:800;">
            ${frappe.utils.escape_html(status)}
          </span>
        </div>

        <button type="button" class="btn ${btnClass} btn-sm dash-btn"
          data-doctype="${doctype}"
          style="width:100%; border-radius:10px;">
          ${btnText}
        </button>
      </div>
    </div>
  `;
}

