    ? frappe.datetime.str_to_user(frm.doc.effective_date)
    : "-";

  const refDate = frm.doc.reference_date
    ? frappe.datetime.str_to_user(frm.doc.reference_date)
    : "-";

  const imgUrl = emp?.image ? frappe.utils.escape_html(emp.image) : "";
