    ? `<img src="${imgUrl}" style="width:52px; height:52px; border-radius:999px; object-fit:cover; border:1px solid #e9ecef;" />`
    : `<div style="width:52px; height:52px; border-radius:999px; background:#f1f3f5; display:flex; align-items:center; justify-content:center; font-weight:800; color:#495057;">
         ${frappe.utils.escape_html((empName || "E").trim().charAt(0).toUpperCase())}
