      <!-- Left: Employee -->
      <div class="esc-info-col" style="flex:1; min-width:300px; display:flex;">
        <div class="card" style="
          padding:14px; border-radius:14px;
          width:100%; height:100%; min-height:${MIN_H}px;
          display:flex; flex-direction:column;
          box-sizing:border-box; overflow:hidden;
        ">
          <div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">
            ${avatar}
            <div style="line-height:1.2; min-width:0;">
              <div style="font-weight:900; font-size:14px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                ${frappe.utils.escape_html(empName)}
              </div>
              <div class="text-muted" style="font-size:12px;">${frappe.utils.escape_html(empId)}</div>
            </div>
          </div>

          <div style="display:grid; gap:6px;">
            <div><span class="text-muted">${__("Date of Joining")}:</span> <b>${frappe.utils.escape_html(doj)}</b></div>
            <div><span class="text-muted">${__("Department")}:</span> <b>${frappe.utils.escape_html(emp?.department || "-")}</b></div>
            <div><span class="text-muted">${__("Office")}:</span> <b>${frappe.utils.escape_html(emp?.custom_office || "-")}</b></div>
            <div><span class="text-muted">${__("Current Designation")}:</span> <b>${frappe.utils.escape_html(emp?.designation || "-")}</b></div>
          </div>
        </div>
      </div>

      <!-- Right: Case Details -->
      <div class="esc-info-col" style="flex:1; min-width:300px; display:flex;">
        <div class="card" style="
          padding:14px; border-radius:14px;
