              <div><span class="text-muted">${__("Case Type")}:</span> <b>${frappe.utils.escape_html(frm.doc.case_type || "-")}</b></div>
              <div><span class="text-muted">${__("Effective Date")}:</span> <b>${frappe.utils.escape_html(eff)}</b></div>
