// =========================
// NEXT ACTION LOGIC (English sources)
// =========================
function get_next_action(frm, { hr05, hr07, hr08, hr09 }) {
  const APPROVED = "Approved"; // final state in linked doctypes
  const case_state = (frm.doc.workflow_state || "").trim();
  const resignation = is_resignation_case(frm);

  // ✅ If statement already issued -> no next action needed
  if (case_state === "Issued") {
    return { label: __("Statement has been issued."), action: "NONE" };
  }

  // ✅ If closed but not issued -> next is Issue Statement
  if (case_state === "Approved / Closed") {
    return { label: __("Case is closed. Proceed to issue statement."), action: "ISSUE" };
  }

  // Only resignation requires HR05
  if (resignation) {
    if (!hr05.exists || hr05.state !== APPROVED)
      return { label: __("Complete HR05 (Resignation Request)"), action: "HR05" };
  }

  if (!hr07.exists || hr07.state !== APPROVED)
    return { label: __("Complete HR07 (Exit Interview)"), action: "HR07" };

  if (!hr08.exists || hr08.state !== APPROVED)
    return { label: __("Complete HR08 (Clearance)"), action: "HR08" };

  if (!hr09.exists || hr09.state !== APPROVED)
    return { label: __("Complete HR09 (Final Dues Statement)"), action: "HR09" };

  return { label: __("All steps completed. Proceed to close case"), action: "DONE" };
}
// =========================
// DATA FETCHERS
// =========================
function get_doc_status_by_case(doctype, case_name) {
  return new Promise((resolve) => {
    frappe.call({
      method: "frappe.client.get_value",
      args: {
        doctype,
        filters: { case: case_name },
        fieldname: ["name", "workflow_state"]
      },
      callback: function (r) {
        const msg = r.message || null;
        if (msg && msg.name) resolve({ exists: true, name: msg.name, state: msg.workflow_state });
        else resolve({ exists: false, name: null, state: null });
      }
    });
  });
}

function get_employee_brief(employee_id) {
  return new Promise((resolve) => {
    if (!employee_id) return resolve(null);

    frappe.call({
      method: "frappe.client.get_value",
      args: {
        doctype: "Employee",
        filters: { name: employee_id },
        fieldname: ["employee_name", "date_of_joining", "department", "custom_office", "designation", "image"]
      },
      callback: (r) => resolve(r.message || null)
    });
  });
}

// =========================
// OPEN / CREATE LINKED DOC
// =========================
function open_or_create_by_case(frm, target_doctype) {
  frappe.call({
    method: "frappe.client.get_value",
    args: {
      doctype: target_doctype,
      filters: { case: frm.doc.name,employee:frm.doc.employee },
      fieldname: "name"
    },
    callback: function (r) {
      const name = r.message && r.message.name;

      if (name) {
        frappe.set_route("Form", target_doctype, name);
      } else {
        frappe.new_doc(target_doctype, {
          case: frm.doc.name,
          employee: frm.doc.employee
        });
      }
    }
  });
}

/*******************************************************
 *  Interview Round - Committee Members Weight Validation
 *  - Disable Save button if total weight != 100
 *  - Also block save with frappe.throw as backup
 *******************************************************/

const TABLE_FIELD = "committee_members";
const CHILD_DOCTYPE = "Committee Member";
const MAX_TOTAL = 100;

function get_total(frm) {
  let total = 0;
  (frm.doc[TABLE_FIELD] || []).forEach(r => {
    total += flt(r.weight);
  });
  return total;
}

function is_member_duplicate(frm, member_id, current_row_name) {
  let is_duplicate = false;
  (frm.doc[TABLE_FIELD] || []).forEach(row => {
    if (row.name !== current_row_name && row.member === member_id) {
      is_duplicate = true;
    }
  });
  return is_duplicate;
}

// ===== دالة تعطيل/تفعيل زر الحفظ فعلياً =====
function control_save_button(frm) {
  const total = get_total(frm);
  
  // تحديد زر الحفظ بعدة طرق لضمان الوصول إليه
  const save_btn = $(`
    button[data-original-title="Save"],
    button:contains("Save"),
    button:contains("حفظ"),
    .primary-action:contains("Save"),
    .primary-action:contains("حفظ"),
    .form-dashboard-section .btn-primary,
    [data-btn="save"]
  `).filter(function() {
    return $(this).attr('type') !== 'submit' || $(this).closest('form').length === 0;
  }).first();

  if (total === MAX_TOTAL) {
    // ✅ تفعيل الزر
    save_btn.prop('disabled', false)
            .css({ opacity: '1', 'pointer-events': 'auto', cursor: 'pointer' })
            .removeClass('disabled')
            .off('click.save_blocker');
    
    frm.page.set_indicator(__('✓ Ready to Save'), 'green');
    frm.__save_blocked = false;
  } else {
    // ❌ تعطيل الزر فعلياً
    save_btn.prop('disabled', true)
            .css({ opacity: '0.5', 'pointer-events': 'none', cursor: 'not-allowed' })
            .addClass('disabled');
    
    // منع النقر بأي طريقة
    save_btn.off('click.save_blocker').on('click.save_blocker', function(e) {
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();
      return false;
    });
    
    const diff = Math.abs(MAX_TOTAL - total);
    frm.page.set_indicator(
      total < MAX_TOTAL
        ? __('⚠ Missing {0}% (Save Disabled)', [diff])
        : __('⚠ Exceeded by {0}% (Save Disabled)', [diff]),
      'orange'
    );
    frm.__save_blocked = true;
  }
}

// ===== المنع النهائي للحفظ (نسخة احتياطية) =====
function validate_total_or_throw(frm) {
  const total = get_total(frm);

  if (total !== MAX_TOTAL) {
    const diff = Math.abs(MAX_TOTAL - total);
    frappe.throw(
      total < MAX_TOTAL
        ? __("⚠️ لا يمكن الحفظ: مجموع الأوزان يجب أن يكون 100%. الحالي: {0}%. المتبقي: {1}%.", [total, diff])
        : __("⚠️ لا يمكن الحفظ: مجموع الأوزان يجب أن يكون 100%. الحالي: {0}%. الزيادة: {1}%.", [total, diff])
    );
  }
}

// ===== مراقبة مستمرة لتحديث حالة الزر =====
function start_save_button_monitoring(frm) {
  if (frm.__save_monitor) return; // منع التكرار
  
  frm.__save_monitor = setInterval(() => {
    if (frm.page && frm.page.wrapper && frm.page.wrapper.is(':visible')) {
      control_save_button(frm);
    }
  }, 500); // تحديث كل نصف ثانية
}

function stop_save_button_monitoring(frm) {
  if (frm.__save_monitor) {
    clearInterval(frm.__save_monitor);
    frm.__save_monitor = null;
  }
}

/*******************************************************
 *  Child Table Events
 *******************************************************/
frappe.ui.form.on(CHILD_DOCTYPE, {
  weight_focus(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    row.__prev_weight = flt(row.weight);
  },

  weight(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    const total = get_total(frm);
    const remaining = MAX_TOTAL - total;

    if (total > MAX_TOTAL) {
      frappe.msgprint(__("Total weight cannot exceed 100. You exceeded by: {0}", [Math.abs(remaining)]));
      frappe.model.set_value(cdt, cdn, "weight", row.__prev_weight || 0);
      control_save_button(frm);
      return;
    }

    frappe.show_alert({
      message: __("المتبقي: {0}", [remaining]),
      indicator: total === MAX_TOTAL ? "green" : "orange"
    });

    control_save_button(frm);
  },

  member(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (row.member && is_member_duplicate(frm, row.member, row.name)) {
      frappe.msgprint(__("هذا العضو مضاف مسبقاً في القائمة، يرجى اختيار عضو آخر."));
      frappe.model.set_value(cdt, cdn, "member", "");
    }
  },

  committee_members_add: function(frm) {
    setTimeout(() => control_save_button(frm), 100);
  },
  committee_members_remove: function(frm) {
    setTimeout(() => control_save_button(frm), 100);
  }
});

/*******************************************************
 *  Parent Doctype Events
 *******************************************************/
frappe.ui.form.on("Interview Round", {
  onload(frm) {
    start_save_button_monitoring(frm);
    setTimeout(() => control_save_button(frm), 300);
  },

  refresh(frm) {
    start_save_button_monitoring(frm);
    control_save_button(frm);
  },

  before_unload(frm) {
    stop_save_button_monitoring(frm);
  },

  validate(frm) {
    // تحقق نهائي كطبقة حماية إضافية
    validate_total_or_throw(frm);
  },

  committee_members: function(frm) {
    setTimeout(() => control_save_button(frm), 100);
  }
});

frappe.ui.form.on('Employee Asset', {
    employee: function(frm) {
        if (!frm.doc.employee) {
            frappe.msgprint(__("Please select an employee first"));
            return;
        }

        // Show loading
        frappe.show_alert({
            message: __('Fetching employee information and assets for {0}...', [frm.doc.employee]),
            indicator: 'orange'
        });

        // First, fetch employee information
        frappe.call({
            method: 'frappe.client.get',
            args: {
                doctype: 'Employee',
                name: frm.doc.employee
            },
            callback: function(employee_response) {
                if (employee_response.message) {
                    var employee = employee_response.message;

                    // Fill employee information fields
                    frm.set_value('employee_name', employee.employee_name || '');
                    frm.set_value('employee_number', employee.employee_number || '');
                    frm.set_value('employee_phone_number', employee.cell_number || employee.phone || '');
                    frm.set_value('designation', employee.designation || '');
                    frm.set_value('department', employee.department || '');

                    // If you have a custom field for branch/company
                    if (frm.fields_dict.branch) {
                        frm.set_value('branch', employee.branch || '');
                    }
                }

                // Now fetch assets for the employee
                frappe.call({
                    method: 'moi_app.utils.fetch_employee_assets',
                    args: {
                        employee: frm.doc.employee
                    },
                    freeze: true,
                    freeze_message: __('Loading assets...'),
                    callback: function(r) {
                        if (r.message && r.message.length > 0) {
                            // Clear existing rows ONLY if we have data
                            frm.clear_table('assets');

                            // Populate child table
                            r.message.forEach(function(asset) {
                                let row = frm.add_child('assets');
                                row.item_name = asset.item_name_with_manufacturer;
                                row.item_origin_number = asset.assets_origin_number;
                                row.item_type = asset.item_type;
                                row.quantity = asset.total_quantity;
                                row.item = asset.item_code;
                                row.notes = asset.item_type == 'تقنيات' ? asset.assets_description : '';
                            });

                            // Refresh form to show new rows
                            frm.refresh_field('assets');

                            frappe.show_alert({
