function calculate_scores(frm) {

    if (!frm.doc.member_evaluations || !frm.doc.committee_members) {
        frm.set_value('final_score', 0);
        return;
    }

    var member_totals = {};
    var member_max_totals = {};
    var member_weights = {};

    // 1️⃣ قراءة وزن كل عضو من Interview
    (frm.doc.committee_members || []).forEach(function(row) {
        if (row.member) {
            member_weights[row.member] = row.weight || 0;
        }
    });

    // 2️⃣ جمع العلامات + العلامة الكاملة لكل عضو
    (frm.doc.member_evaluations || []).forEach(function(row) {

        if (!row.committee_member) return;

        var score = row.score || 0;
        var max_score = row.max_score || 0;

        member_totals[row.committee_member] =
            (member_totals[row.committee_member] || 0) + score;

        member_max_totals[row.committee_member] =
            (member_max_totals[row.committee_member] || 0) + max_score;
    });

    // 3️⃣ حساب النتيجة النهائية
    var final_score = 0;

    Object.keys(member_totals).forEach(function(member) {

        var total = member_totals[member] || 0;
        var max_total = member_max_totals[member] || 1;
        var weight = member_weights[member] || 0;

        // نسبة العضو (0–100)
        var percentage = (total / max_total) * 100;

        // تطبيق وزن العضو
        final_score += percentage * (weight / 100);
    });

    frm.set_value('final_score', final_score.toFixed(2));
}

