async function update_custom_fields_from_first_asset(frm) {
    if (!frm.doc.assets || frm.doc.assets.length === 0) {
        // Clear all fields
        ['custom_asset', 'custom_item', 'custom_from_employee', 'custom_to_employee'].forEach(field => {
            frm.set_value(field, '');
        });
        return;
    }

    const first_row = frm.doc.assets[0];

    // Set Asset ID immediately
    frm.set_value('custom_asset', first_row.asset);

    try {
        // Fetch Asset document (for item_name)
        if (first_row.asset) {
            const asset_doc = await frappe.db.get_doc('Asset', first_row.asset);
            frm.set_value('custom_item', asset_doc.item_name || '');
        }

        // Fetch From Employee name
        if (first_row.from_employee) {
            const from_emp = await frappe.db.get_value('Employee', first_row.from_employee, 'employee_name');
            frm.set_value('custom_from_employee', from_emp.message.employee_name || '');
        } else {
            frm.set_value('custom_from_employee', '');
        }

        // Fetch To Employee name
        if (first_row.to_employee) {
            const to_emp = await frappe.db.get_value('Employee', first_row.to_employee, 'employee_name');
            frm.set_value('custom_to_employee', to_emp.message.employee_name || '');
        } else {
            frm.set_value('custom_to_employee', '');
        }

    } catch (err) {
        console.error('Error updating custom fields:', err);
        frappe.show_alert({
            message: __('Error loading asset/employee data'),
            indicator: 'orange'
        });
    }
}

