frappe.ui.form.on('Maintenance Request', {
    refresh: function(frm) {
        // --- ضبط خريطة السيكشنات: key = fieldname للـ Section Break
        // قيمة كل مفتاح = مصفوفة الرولات المسموح لها برؤية هذا السيكشن
        // اترك المصفوفة فارغة [] لتجعل السيكشن مرئي للجميع
        const sections = {
            // استبدل هذه الأسماء بأسماء Section Break الحقيقية في Doctype
            "connections": ["Technician"],                // يظهر فقط للتقنيين
            "request_processing": ["Technician"],// يظهر للمدراء ورؤساء الصيانة
            "closing": [],                               // يظهر للجميع
            "request": [],                            // يظهر للجميع
        };

        // جلب رولات اليوزر الحالية
        const user_roles = (frappe.user_roles || []).map(r => r.toString());

        // دالة مساعدة: هل لدى اليوزر أي من الرولات المطلوبة؟
        function hasAnyRole(requiredRoles) {
            if (!requiredRoles || requiredRoles.length === 0) return true; // مرئي للجميع
            for (let r of requiredRoles) {
                if (user_roles.indexOf(r) !== -1) return true;
            }
            return false;
        }

        // تطبيق الإظهار/الإخفاء لكل سيكشن
        Object.keys(sections).forEach(function(request) {
            const allowedRoles = sections[request];
            const show = hasAnyRole(allowedRoles);

            // 1) إخفاء/إظهار الـ Section Break نفسه (يعمل في معظم نسخ Frappe)
            try {
                frm.set_df_property(request, 'hidden', !show);
            } catch (e) {
                // إذا لم يعمل set_df_property على Section Break، نستخدم toggle_display على أول حقل بعد السيكشن
                console.warn('set_df_property failed for', request, e);
            }

            // 2) لضمان إخفاء كل الحقول داخل السيكشن (fallback)
            // ضع هنا أسماء الحقول التي تنتمي لكل سيكشن إن أردت ضمان الإخفاء الكامل
            // مثال: fields_in_section = { "section_1": ["field_a","field_b"], ... }
        });

    }
});

