// ===== 2. دالة إضافة الزر فوق الجدول =====
function add_button_above_grid(frm) {
    if (frm.__grid_button_added) return;
    
    const grid = frm.fields_dict['staffing_details']?.grid;
    if (!grid) return;
    
    // إضافة الزر في شريط أدوات الجدول
    grid.add_custom_button(__('Add Job Requisitions'), function() {
        show_department_filter_dialog(frm);
    });
    
    frm.__grid_button_added = true;
}

// ===== 3. دالة إظهار Dialog الفلترة =====
function show_department_filter_dialog(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Job Requisition',
            filters: { docstatus: ['!=', 2] },
            fields: ['department'],
            limit_page_length: 1000
        },
        callback: function(r) {
            const depts = [...new Set((r.message || []).map(d => d.department).filter(Boolean))];
            const dept_options = [''].concat(depts);

            const dialog = new frappe.ui.Dialog({
                title: __('Filter by Department'),
                fields: [
                    {
                        label: __('Department'),
                        fieldname: 'department',
                        fieldtype: 'Select',
                        options: dept_options,
                        description: __('Leave empty to fetch all departments'),
                        reqd: 0
                    }
                ],
                primary_action_label: __('Fetch'),
                primary_action(values) {
                    dialog.hide();
                    fetch_and_merge_requisitions(frm, values.department);
                },
                secondary_action_label: __('Cancel'),
                secondary_action() { dialog.hide(); }
            });
            dialog.show();
        }
    });
}

// ===== 4. دالة تنظيف الصفوف الفارغة =====
function remove_empty_rows(frm, table_field) {
    const rows = frm.doc[table_field] || [];
    const empty_rows = rows.filter(row => !row.job_req && !row.designation && !row.departments);
    if (empty_rows.length > 0) {
        empty_rows.forEach(row => {
            frm.doc[table_field] = rows.filter(r => r.name !== row.name);
        });
        frm.refresh_field(table_field);
    }
}

// ===== 5. دالة حساب المجموع الكلي للميزانية =====
function calculate_total_budget(frm) {
    const rows = frm.doc.staffing_details || [];
    let total = 0;
    rows.forEach(row => {
        if (row.total_estimated_cost) {
            total += row.total_estimated_cost;
        } else if (row.estimated_cost_per_position && row.vacancies) {
            total += row.estimated_cost_per_position * row.vacancies;
        }
    });
    if (frm.fields_dict['total_estimated_budget']) {
        frm.set_value('total_estimated_budget', total);
    } else if (frm.fields_dict['total_budget']) {
        frm.set_value('total_budget', total);
    }
}

// ===== 6. الدالة الرئيسية: جلب الشواغر مع فلتر القسم =====
function fetch_and_merge_requisitions(frm, filter_department) {
    const filters = { docstatus: ['!=', 2] };
    
    if (filter_department) {
        filters.department = filter_department;
    }

    console.log('=== الفلاتر المطبقة ===');
    console.log('Department:', filter_department || 'All');

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Job Requisition',
            filters: filters,
            fields: [
                'name', 'designation', 'department', 'no_of_positions',
                'expected_compensation', 'requested_by', 'requested_by_name',
                'description', 'posting_date', 'expected_by', 'company', 'owner', 'status'
            ],
            limit_page_length: 100
        },
        freeze: true,
        freeze_message: __('جاري جلب طلبات التوظيف...'),
        callback: function(r) {
            if (r.message && r.message.length) {
                console.log('=== بيانات Job Requisition المستلمة ===');
                console.log('العدد:', r.message.length);
                
                const new_items = r.message.filter(new_req => {
                    const exists = frm.doc.staffing_details.some(row => row.job_req === new_req.name);
                    return !exists;
                });

                if (new_items.length > 0) {
                    new_items.forEach(req => {
                        let row = frm.add_child('staffing_details');
                        row.job_req = req.name;
                        row.designation = req.designation;
                        row.departments = req.department;
                        row.vacancies = req.no_of_positions;
                        row.estimated_cost_per_position = req.expected_compensation;
                        
                        if (req.expected_compensation && req.no_of_positions) {
                            row.total_estimated_cost = req.expected_compensation * req.no_of_positions;
                        }
                    });
                    
                    remove_empty_rows(frm, 'staffing_details');
                    calculate_total_budget(frm);
                    frm.refresh_field('staffing_details');
                    
                    frappe.show_alert({
                        message: __('تمت إضافة ' + new_items.length + ' شاغر جديد بنجاح'),
                        indicator: 'green'
                    });
                } else {
                    frappe.show_alert({
                        message: __('جميع الشواغر المتاحة تمت إضافتها مسبقاً'),
                        indicator: 'orange'
                    });
                }
            } else {
                frappe.show_alert({
                    message: __('لا توجد طلبات توظيف تطابق الفلتر المحدد'),
                    indicator: 'red'
                });
            }
        }
    });
}

