// ===== 1. CONFIG & PRELOAD HELPERS =====
const CONFIG = [
  { table: "committee_members", links: [{ field: "member", doctype: "Employee", title_field: "employee_name" }] },
  { table: "member_evaluations", links: [
      { field: "committee_member", doctype: "Employee", title_field: "employee_name" },
      { field: "question", doctype: "Question Panel", title_field: "question" }
    ] 
  }
];

function set_link_title_cache(doctype, name, title) {
  frappe._link_titles = frappe._link_titles || {};
  frappe._link_titles[doctype] = frappe._link_titles[doctype] || {};
  frappe._link_titles[doctype][name] = title;
  frappe._link_titles[`${doctype}::${name}`] = title;
}

async function preload_titles(frm, table_field, link_field, doctype, title_field) {
  const rows = frm.doc[table_field] || [];
  const ids = [...new Set(rows.map(r => r[link_field]).filter(Boolean))];
  if (!ids.length) return;
  const list = await frappe.db.get_list(doctype, {
    filters: { name: ["in", ids] },
    fields: ["name", title_field],
    limit: 999
  });
  (list || []).forEach(d => set_link_title_cache(doctype, d.name, d[title_field] || d.name));
}

async function preload_for_table(frm, table_field) {
  const table_cfg = CONFIG.find(c => c.table === table_field);
  if (!table_cfg) return;
  for (const l of table_cfg.links) {
    await preload_titles(frm, table_field, l.field, l.doctype, l.title_field);
  }
  frm.refresh_field(table_field);
}

// ===== 2. CORE: Load Data (Strict Distribution) =====
async function load_interview_round_data(frm, round_name) {
  if (!round_name || frm.__loading_round) return;

  frm.doc.committee_members = [];
  frm.doc.member_evaluations = [];
  frm.refresh_field('committee_members');
  frm.refresh_field('member_evaluations');

  frm.__loading_round = true;
  
  try {
    const r = await frappe.call({
      method: 'frappe.client.get',
      args: { doctype: 'Interview Round', name: round_name }
    });

    const doc = r.message;
    if (!doc) return;

    let tech_member = null;
    let admin_member = null;
    let hr_member = null;
    
    (doc.committee_members || []).forEach(m => {
      let cm = frm.add_child('committee_members');
      cm.member = m.member;
      cm.member_type = m.member_type;
      cm.weight = m.weight;

      if (m.member_type === "فني" && !tech_member) tech_member = m.member;
      if (m.member_type === "إداري" && !admin_member) admin_member = m.member;
      if (m.member_type === "HR" && !hr_member) hr_member = m.member;
    });

    (doc.custom_technical_questions || []).forEach(q => {
      let me = frm.add_child('member_evaluations');
      me.committee_member = tech_member || hr_member; 
      me.member_type = "Technical";
      me.question = q.question; 
      me.max_score = q.score;
      set_link_title_cache("Question Panel", q.question, q.question);
    });

    (doc.custom_administrative_questions || []).forEach(q => {
      let me = frm.add_child('member_evaluations');
      me.committee_member = admin_member || hr_member;
      me.member_type = "Administrative";
      me.question = q.question; 
      me.max_score = q.score;
      set_link_title_cache("Question Panel", q.question, q.question);
    });

    if (hr_member) {
      const q_panel = await frappe.call({
        method: 'frappe.client.get_list',
        args: {
          doctype: 'Question Panel',
          filters: { member_type: "HR" },
          fields: ['name', 'max_score'],
          order_by: 'idx asc'
        }
      });
      (q_panel.message || []).forEach(q => {
        let me = frm.add_child('member_evaluations');
        me.committee_member = hr_member;
        me.member_type = "HR";
        me.question = q.name;
        me.max_score = q.max_score;
      });
    }

    frm.refresh_field('committee_members');
    frm.refresh_field('member_evaluations');
    
    setTimeout(async () => {
      await preload_for_table(frm, 'committee_members');
      await preload_for_table(frm, 'member_evaluations');
      calculate_scores(frm);
    }, 500);

  } catch (error) {
    console.error(error);
  } finally {
    frm.__loading_round = false;
  }
}

// ===== 3. SCORE CALCULATION (المنطق الذي كان ينقصك) =====
function calculate_scores(frm) {
  if (!frm.doc.member_evaluations || !frm.doc.committee_members) {
    frm.set_value('final_score', 0);
    return;
  }

  let stats = {};

  // جلب الأوزان
  (frm.doc.committee_members || []).forEach(m => {
    if (m.member) {
      stats[m.member] = { weight: m.weight || 0, total: 0, max: 0 };
    }
  });

  // جمع العلامات لكل عضو
  (frm.doc.member_evaluations || []).forEach(row => {
    if (row.committee_member && stats[row.committee_member]) {
      stats[row.committee_member].total += (row.score || 0);
      stats[row.committee_member].max += (row.max_score || 0);
    }
  });

  let final = 0;
  Object.keys(stats).forEach(id => {
    if (stats[id].max > 0) {
      final += (stats[id].total / stats[id].max) * stats[id].weight;
    }
  });

  frm.set_value('final_score', final.toFixed(3));
}

