// ✅ دالة فحص وتحديث الحقول الأساسية - تظهر فقط التي فيها بيانات
async function update_base_fields_with_data(job_title, base_fields_config) {
    let container = document.getElementById('moi-base-fields-container');
    let count_label = document.getElementById('moi-fields-count');
    
    if (!container) return;
    
    container.innerHTML = `<p style="color:#666;padding:15px;text-align:center;">
        <i class="fa fa-spinner fa-spin"></i> جاري فحص البيانات...
    </p>`;
    
    try {
        // 1. جلب المتقدمين لهذا الشاغر
        let filters = {};
        if (job_title && job_title !== "All") {
            filters.job_title = job_title;
        }
        
        // جلب جميع الحقول الأساسية للفحص
        let fields_to_check = ["name", ...base_fields_config.map(f => f.value)];
        
        let applicants = await frappe.db.get_list('Job Applicant', {
            filters: filters,
            fields: fields_to_check,
            limit_page_length: 200  // عينة كافية للفحص
        });
        
        if (applicants.length === 0) {
            // إذا لا يوجد متقدمين، اعرض كل الحقول مع القيم الافتراضية
            render_base_fields(container, base_fields_config, base_fields_config.map(f => f.value));
            if (count_label) count_label.innerHTML = `<i class="fa fa-info-circle"></i> لا توجد بيانات، تم عرض جميع الحقول`;
            return;
        }
        
        // 2. ✅ فحص كل حقل أساسي: هل يحتوي على بيانات غير فارغة؟
        let fields_with_data = [];
        
        base_fields_config.forEach(field => {
            let has_data = applicants.some(app => {
                let val = app[field.value];
                // يعتبر الحقل فارغاً إذا كان: null, undefined, "", أو سلسلة فارغة بعد القص
                return val !== null && val !== undefined && String(val).trim() !== "";
            });
            
            if (has_data) {
                fields_with_data.push(field.value);
            }
        });
        
        // 3. ✅ عرض الحقول التي تحتوي على بيانات فقط (مع تحديدها تلقائياً)
        let fields_to_show = base_fields_config.filter(f => fields_with_data.includes(f.value));
        
        if (fields_to_show.length === 0) {
            container.innerHTML = `<p style="color:#999;padding:15px;text-align:center;">
                لا توجد حقول أساسية تحتوي على بيانات لهذا الشاغر
            </p>`;
        } else {
            render_base_fields(container, fields_to_show, fields_with_data);
        }
        
        // تحديث العداد
        if (count_label) {
            count_label.innerHTML = `<i class="fa fa-check-circle" style="color: #1D6F42;"></i> 
                تم عرض <b>${fields_to_show.length}</b> حقل يحتوي على بيانات (محدد تلقائياً)`;
        }
        
    } catch (e) {
        console.error("Error checking base fields:", e);
        // Fallback: اعرض كل الحقول مع القيم الافتراضية
        render_base_fields(container, base_fields_config, base_fields_config.filter(f => f.default_checked).map(f => f.value));
        if (count_label) count_label.innerHTML = `<i class="fa fa-warning"></i> حدث خطأ، تم عرض الحقول الافتراضية`;
    }
}

// ✅ دالة عرض الحقول الأساسية في HTML
function render_base_fields(container, fields_to_show, fields_with_data) {
    let html = ``;
    fields_to_show.forEach(f => {
        // ✅ تحديد الحقل تلقائياً إذا كان يحتوي على بيانات
        let is_checked = fields_with_data.includes(f.value) ? 'checked' : '';
        html += `
            <div style="margin:6px 0;display:flex;align-items:center;">
                <input type="checkbox" class="moi-base" value="${f.value}" ${is_checked}
                    style="margin-right:8px;width:16px;height:16px;">
                <label style="cursor:pointer;font-weight:500;color:#333;">${f.label}</label>
            </div>`;
    });
    container.innerHTML = html;
}

// ✅ دالة تحديث الأسئلة الديناميكية - تظهر المرتبطة فقط (محددة تلقائياً)
async function update_dynamic_questions_no_permission(job_title, all_questions) {
    let container = document.getElementById('moi-dyn-questions-container');
    
    if (!container) return;
    
    container.innerHTML = `<p style="color:#666;padding:15px;text-align:center;">
        <i class="fa fa-spinner fa-spin"></i> جاري تحميل الأسئلة...
    </p>`;
    
    try {
        let filters = {};
        if (job_title && job_title !== "All") {
            filters.job_title = job_title;
        }
        
        let applicants = await frappe.db.get_list('Job Applicant', {
            filters: filters,
            fields: ['name', 'job_title'],
            limit_page_length: 500
        });
        
        if (applicants.length === 0) {
            container.innerHTML = `<p style="color:#999;padding:15px;text-align:center;">
                لا يوجد متقدمين لهذا الشاغر
            </p>`;
            return;
        }
        
        let questions_set = new Set();
        
        // جلب الأسئلة من إجابات المتقدمين
        for (let i = 0; i < applicants.length && i < 100; i++) {
            let app = applicants[i];
            try {
                let full_doc = await frappe.call({
                    method: "frappe.desk.form.load.getdoc",
                    args: {
                        doctype: "Job Applicant",
                        name: app.name
                    }
                });
                
                if (full_doc && full_doc.docs) {
                    let doc = full_doc.docs.find(d => d.doctype === 'Job Applicant');
                    
                    if (doc) {
                        let child_table_field = find_child_table_field(doc, [
                            'custom_dynamic_answers', 
                            'dynamic_answers', 
                            'answers',
                            'custom_answers',
                            'interview_answers'
                        ]);
                        
                        if (child_table_field && Array.isArray(doc[child_table_field])) {
                            doc[child_table_field].forEach(answer => {
                                if (answer && answer.question) {
                                    questions_set.add(answer.question);
                                }
                            });
                        }
                    }
                }
            } catch (e) {
                console.warn("فشل جلب متقدم:", app.name, e);
            }
        }
        
        let filtered_questions = [];
        
        if (questions_set.size > 0) {
            filtered_questions = all_questions.filter(q => questions_set.has(q.question));
        }
        
        if (filtered_questions.length === 0 && all_questions.length > 0) {
            filtered_questions = all_questions;
        }
        
        // ✅ عرض الأسئلة مع تحديدها تلقائياً (checked)
        if (filtered_questions.length === 0) {
            container.innerHTML = `<p style="color:#999;padding:15px;text-align:center;">
                لا توجد أسئلة ديناميكية متاحة
            </p>`;
        } else {
            let dyn_html = ``;
            filtered_questions.forEach((q) => {
                let safe_q = q.question.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
                dyn_html += `
                    <div style="margin:6px 0;display:flex;align-items:center;">
                        <input type="checkbox" class="moi-dyn" value="${safe_q}" checked
                            style="margin-right:8px;width:16px;height:16px;">
                        <label style="cursor:pointer;font-weight:400;color:#555;flex:1;">${q.question}</label>
                    </div>`;
            });
            container.innerHTML = dyn_html;
        }
        
    } catch (e) {
        console.error("Error updating questions:", e);
        
        // Fallback: اعرض كل الأسئلة مع تحديدها
        if (all_questions.length > 0) {
            let dyn_html = ``;
            all_questions.forEach((q) => {
                let safe_q = q.question.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
                dyn_html += `
                    <div style="margin:6px 0;display:flex;align-items:center;">
                        <input type="checkbox" class="moi-dyn" value="${safe_q}" checked
                            style="margin-right:8px;width:16px;height:16px;">
                        <label style="cursor:pointer;font-weight:400;color:#555;flex:1;">${q.question}</label>
                    </div>`;
            });
            container.innerHTML = dyn_html;
        } else {
            container.innerHTML = `<p style="color:#999;padding:15px;text-align:center;">
                لا توجد أسئلة ديناميكية متاحة
            </p>`;
        }
    }
}

// دالة التصدير الاحترافية
async function export_to_excel_professional(job_title, base_fields, dynamic_questions) {
    try {
        // 1. فلترة المتقدمين
        let filters = {};
        if (job_title && job_title !== "All") {
            filters.job_title = job_title;
        }
        
        let fields = ["name", ...base_fields];
        
        let applicants_list = await frappe.db.get_list('Job Applicant', {
            filters: filters,
            fields: fields,
            order_by: 'creation desc',
            limit_page_length: 10000
        });
        
        if (applicants_list.length === 0) {
            frappe.msgprint("لا توجد بيانات مطابقة للبحث");
            return;
        }
        
        // 2. جلب المستندات كاملة مع Child Table
        let applicants = [];
        let questions_set = new Set(dynamic_questions);
        
        for (let i = 0; i < applicants_list.length; i += 20) {
            let batch = applicants_list.slice(i, i + 20);
            
            for (let app of batch) {
                try {
                    let full_doc = await frappe.call({
                        method: "frappe.desk.form.load.getdoc",
                        args: {
                            doctype: "Job Applicant",
                            name: app.name
                        }
                    });
                    
                    if (full_doc && full_doc.docs) {
                        let doc = full_doc.docs.find(d => d.doctype === 'Job Applicant');
                        
                        if (doc) {
                            let merged_doc = { ...app };
                            let child_table_field = find_child_table_field(doc, [
                                'custom_dynamic_answers', 
                                'dynamic_answers', 
                                'answers',
                                'custom_answers',
                                'interview_answers'
                            ]);
                            
                            if (child_table_field && Array.isArray(doc[child_table_field])) {
                                merged_doc.custom_dynamic_answers = doc[child_table_field];
                            }
                            
                            applicants.push(merged_doc);
                        } else {
                            applicants.push(app);
                        }
                    } else {
                        applicants.push(app);
                    }
                } catch (e) {
                    console.warn("فشل جلب:", app.name, e);
                    applicants.push(app);
                }
            }
        }
        
        // 3. استخراج الإجابات الديناميكية
        let answers_map = {};
        applicants.forEach(app => {
            answers_map[app.name] = {};
            let child_table = app.custom_dynamic_answers;
            
            if (!child_table) {
                for (let key in app) {
                    if (Array.isArray(app[key]) && app[key].length > 0 && app[key][0].doctype === 'Job Dynamic Answer') {
                        child_table = app[key];
                        break;
                    }
                }
            }
            
            if (child_table && Array.isArray(child_table)) {
                child_table.forEach(answer => {
                    if (answer && answer.question) {
                        answers_map[app.name][answer.question] = answer.answer || "";
                    }
                });
            }
        });
        
        // 4. تحضير رؤوس الأعمدة
        let labels = {
            applicant_name: "اسم المتقدم",
            email_id: "البريد الإلكتروني",
            phone_number: "رقم الهاتف",
            status: "الحالة",
            job_title: "المسمى الوظيفي",
            creation: "تاريخ الإنشاء",
            modified: "تاريخ التعديل"
        };
        
        let headers = base_fields.map(f => labels[f] || f);
        headers = headers.concat(dynamic_questions);
        
        // 5. تحضير صفوف البيانات
        let data_rows = [];
        applicants.forEach(app => {
            let row = {};
            
            base_fields.forEach(f => {
                let val = app[f] || "";
                if (val && typeof val === 'string' && val.match(/^\d{4}-\d{2}-\d{2}/)) {
                    val = val.split('T')[0];
                }
                row[labels[f] || f] = val;
            });
            
            let app_answers = answers_map[app.name] || {};
            dynamic_questions.forEach(q => {
                row[q] = app_answers[q] || "";
            });
            
            data_rows.push(row);
        });
        
        // 6. إنشاء Workbook
        let wb = XLSX.utils.book_new();
        let ws = XLSX.utils.json_to_sheet(data_rows, { header: headers });
        
        // 7. تنسيق احترافي
        let col_count = headers.length;
        let row_count = data_rows.length + 1;
        
        let col_widths = headers.map(h => {
            let max_len = h.length;
            data_rows.forEach(row => {
                if (row[h] && String(row[h]).length > max_len) {
                    max_len = String(row[h]).length;
                }
            });
            return { wch: Math.min(Math.max(max_len + 2, 15), 50) };
        });
        ws['!cols'] = col_widths;
        
        // إضافة AutoFilter
        ws['!autofilter'] = { ref: `A1:${XLSX.utils.encode_col(col_count - 1)}${row_count}` };
        
        // تنسيق صف الرأس
        let range = XLSX.utils.decode_range(ws['!ref']);
        for (let C = range.s.c; C <= range.e.c; ++C) {
            let address = XLSX.utils.encode_col(C) + "1";
            if (!ws[address]) continue;
            ws[address].s = {
                font: { bold: true, color: { rgb: "FFFFFF" }, sz: 13 },
                fill: { fgColor: { rgb: "1D6F42" } },
                alignment: { horizontal: "center", vertical: "center", wrapText: true },
                border: {
                    top: { style: "thick", color: { rgb: "000000" } },
                    bottom: { style: "thick", color: { rgb: "000000" } },
                    left: { style: "thick", color: { rgb: "FFFFFF" } },
                    right: { style: "thick", color: { rgb: "FFFFFF" } }
                }
            };
        }
        
        // تنسيق صفوف البيانات
        for (let R = range.s.r + 1; R <= range.e.r; ++R) {
            for (let C = range.s.c; C <= range.e.c; ++C) {
                let address = XLSX.utils.encode_col(C) + (R + 1);
                if (!ws[address]) continue;
                
                let bg_color = (R % 2 === 0) ? { rgb: "F8F9FA" } : { rgb: "FFFFFF" };
                
                ws[address].s = {
                    alignment: { horizontal: "right", vertical: "center" },
                    fill: { fgColor: bg_color },
                    border: {
                        top: { style: "thin", color: { rgb: "000000" } },
                        bottom: { style: "thin", color: { rgb: "000000" } },
                        left: { style: "thin", color: { rgb: "000000" } },
                        right: { style: "thin", color: { rgb: "000000" } }
                    },
                    font: { sz: 11 }
                };
            }
        }
        
        ws['!freeze'] = { xSplit: 0, ySplit: 1 };
        XLSX.utils.book_append_sheet(wb, ws, "المتقدمين");
        
        // 8. تنزيل الملف
        let date_str = frappe.datetime.now_date().replace(/-/g, '');
        let filename = `Job_Applicants_${job_title === "All" ? "All" : job_title}_${date_str}.xlsx`;
        
        XLSX.writeFile(wb, filename, { bookType: 'xlsx', type: 'binary', compression: true });
        
        frappe.show_alert({ message: `✅ تم التنزيل: ${filename}`, indicator: "green" }, 3);
        
    } catch (e) {
        console.error("Export Error:", e);
        frappe.msgprint("❌ خطأ: " + e.message);
    }
}

// دالة البحث عن Child Table
function find_child_table_field(doc, possible_names) {
    for (let name of possible_names) {
        if (doc[name] && Array.isArray(doc[name])) {
            return name;
        }
    }
    
    for (let key in doc) {
        if (Array.isArray(doc[key]) && doc[key].length > 0 && doc[key][0].doctype) {
            return key;
        }
    }
    
    return null;
}

