var calculate_total = function(frm) {
    let total = 0;
    // استبدل maintenance_and_repair_committee بالاسم البرمجي للجدول في الدوكتايب الأساسي
    (frm.doc.maintenance_repair_committee_2 || []).forEach(function(row) {
        total += flt(row.price);
