    // استبدل total_amount بالاسم البرمجي لحقل "الإجمالي"
    frm.set_value('final_total', total);
};

frappe.ui.form.on('Interview', {
    interview_round: function(frm) {
        if (!frm.doc.interview_round) return;

        // جلب بيانات الـ Round لسحب الأسئلة
        frappe.db.get_doc('Interview Round', frm.doc.interview_round).then(round_doc => {
            
            // 1. معالجة الأسئلة الفنية (Technical)
            if (round_doc.custom_technical_questions && round_doc.custom_technical_questions.length > 0) {
                round_doc.custom_technical_questions.forEach(q => {
                    let child = frm.add_child('member_evaluations');
                    child.member_type = "Technical"; 
                    child.tquestion = q.question;    // السؤال النصي
                    child.max_score = q.score;      // العلامة العظمى
                });
            }

            // 2. معالجة الأسئلة الإدارية (Administrative)
            if (round_doc.custom_administrative_questions && round_doc.custom_administrative_questions.length > 0) {
                round_doc.custom_administrative_questions.forEach(q => {
                    let child = frm.add_child('member_evaluations');
                    child.member_type = "HR";
                    child.question = q.question;    // في حال كان الـ HR يستخدم حقل 'question' المرتبط بـ Question Panel
                    child.max_score = q.score;
                });
            }

            // تحديث الجدول في الواجهة
            frm.refresh_field('member_evaluations');
            
            frappe.show_alert({
                message: __("تم جلب {0} سؤال فني وإداري", [
                    (round_doc.custom_technical_questions?.length || 0) + 
                    (round_doc.custom_administrative_questions?.length || 0)
                ]),
                indicator: 'blue'
            });
        });
    }
});

frappe.ui.form.on('Interview', {
    interview_round: function(frm) {
        if (frm.doc.interview_round) {
            // جلب بيانات الدوكتايب الآخر بالكامل
            frappe.db.get_doc('Interview Round', frm.doc.interview_round)
                .then(round_doc => {
                    
                    // مسح الأسئلة القديمة لتجنب التكرار عند تغيير الـ Round
                    frm.clear_table('member_evaluations');

                    // 1. جلب الأسئلة الفنية
                    if (round_doc.custom_technical_questions) {
                        round_doc.custom_technical_questions.forEach(q => {
                            let child = frm.add_child('member_evaluations');
                            child.member_type = "Technical";
                            child.tquestion = q.question; // الحقل النصي في Interview
                            child.max_score = q.score;    // العلامة من الجدول الجديد
                        });
                    }

                    // 2. جلب الأسئلة الإدارية
                    if (round_doc.custom_administrative_questions) {
                        round_doc.custom_administrative_questions.forEach(q => {
                            let child = frm.add_child('member_evaluations');
                            child.member_type = "HR";
                            // ملاحظة: إذا كان الـ HR يستخدم Question Panel، نضع القيمة في حقل question
                            child.question = q.question; 
                            child.max_score = q.score;
                        });
                    }

                    // تحديث الجدول في الشاشة
                    frm.refresh_field('member_evaluations');
                    
                    frappe.show_alert({
                        message: __("تم جلب الأسئلة المحددة في جولة المقابلة"),
                        indicator: 'green'
                    });
                });
        }
    }
});

frappe.ui.form.on('Request for an Oil Change from the Central Garage', {
    // سيتم تنفيذ الكود عند تغيير قيمة "المسافة السابقة"
    previous_request: function(frm) {
        calculate_difference(frm);
    },
    // سيتم تنفيذ الكود عند تغيير قيمة "العداد الحالي"
    current_request: function(frm) {
        calculate_difference(frm);
    }
});

function calculate_difference(frm) {
    // تأكد من استبدال الأسماء بالأسماء البرمجية للحقول لديك
    if (frm.doc.current_request && frm.doc.previous_request) {
        let diff = flt(frm.doc.current_request) - flt(frm.doc.previous_request);
        
        // إذا كانت النتيجة سالبة (خطأ في الإدخال) نضع صفراً أو نتركها
        if (diff < 0) {
            frm.set_value('distance_difference', 0);
        } else {
            frm.set_value('distance_difference', diff);
        }
    } else {
        frm.set_value('distance_difference', 0);
    }
}

