frappe.ui.form.on('Request Car Wash', {
    request_date: function(frm) {
        if (frm.doc.request_date) {
            let booking_time = new Date(frm.doc.request_date);
            let hours = booking_time.getHours();
            let minutes = booking_time.getMinutes();

            // 1. التحقق من ساعات الدوام (من 8 صباحاً حتى 3 مساءً)
            // ملاحظة: الساعة 3 مساءً هي 15 بنظام 24 ساعة
            if (hours < 8 || hours > 15 || (hours === 15 && minutes > 0)) {
                frappe.msgprint({
                    title: __('خارج أوقات الدوام'),
                    indicator: 'orange',
                    message: __('يرجى اختيار وقت بين الساعة 8:00 صباحاً و 3:00 مساءً')
                });
                frm.set_value('request_date', '');
                return;
            }

            // 2. التحقق من وجود حجوزات متداخلة (نصف ساعة)
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Request Car Wash",
                    filters: {
                        "name": ["!=", frm.doc.name],
                        "docstatus": ["<", 2],
                        // فلتر إضافي لتسريع البحث (البحث في حجوزات نفس اليوم فقط)
                        "request_date": [">", frappe.datetime.add_days(frm.doc.request_date, -1)]
                    },
                    fields: ["request_date"]
                },
                callback: function(r) {
                    let is_busy = false;
                    const new_booking = new Date(frm.doc.request_date);

                    if (r.message) {
                        r.message.forEach(booked => {
                            let booked_time = new Date(booked.request_date);
                            let diff = Math.abs(new_booking - booked_time) / (1000 * 60);

                            if (diff < 30) {
                                is_busy = true;
                            }
                        });
                    }

                    if (is_busy) {
                        frappe.msgprint({
                            title: __('وقت محجوز'),
                            indicator: 'red',
                            message: __('هذا الوقت غير متاح، يوجد حجز آخر في غضون 30 دقيقة. يرجى اختيار وقت آخر.')
                        });
                        frm.set_value('request_date', '');
                    } else {
                        frappe.show_alert({
                            message: __('الوقت متاح ضمن ساعات الدوام'),
                            indicator: 'green'
                        }, 5);
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Attendance Exception', {
    fetch_employee: function(frm) {
        fetch_employees(frm);
    },

    clear_employees: function(frm) {
        frm.clear_table('employees');
        frm.refresh_field('employees');
    }
});

function fetch_employees(frm) {
    if (!frm.doc.company && !frm.doc.department && !frm.doc.designation && !frm.doc.employee_name) {
        frappe.msgprint(__('Please select at least one filter'));
        return;
    }

    frappe.call({
        method: "get_filtered_employees",
        args: {
            company: frm.doc.company,
            department: frm.doc.department,
            designation: frm.doc.designation,
            employee_name: frm.doc.employee_name
        },
        freeze: true,
        freeze_message: __('Fetching employees...'),
        callback: function(r) {
            if (!r.message) return;

            const employees = r.message || [];
            const existing = new Set(
                (frm.doc.employees || []).map(row => row.employee)
            );

            let added = 0;

            employees.forEach(emp => {
                if (!existing.has(emp.employee)) {
                    let row = frm.add_child('employees');
                    row.employee = emp.employee;
                    row.full_name = emp.full_name;
                    row.department = emp.department;
                    row.designation = emp.designation;
                    row.gender = emp.gender;
                    existing.add(emp.employee);
                    added++;
                }
            });

            frm.refresh_field('employees');

            frappe.msgprint(
                __('Fetched: {0} | Added: {1}', [employees.length, added])
            );
        }
    });
}

frappe.ui.form.on('Leave Application', {
    refresh: function(frm) {
        // Define which roles can edit the employee field
        const can_edit_roles = ['HR User', 'HR Manager', 'System Manager'];
        const can_edit = can_edit_roles.some(role => frappe.user.has_role(role));

        // If user does NOT have any of the allowed roles, make employee field read-only
        if (!can_edit) {
            frm.set_df_property('employee', 'read_only', 1);
        }

        // Check if it's a new form and the employee field is empty
        if (frm.is_new() && !frm.doc.employee) {
            // Fetch the employee linked to the current user
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Employee',
                    filters: { 'user_id': frappe.session.user },
                    fieldname: ['name']
                },
                callback: function(response) {
                    let employee_id = response.message.name;
                    if (employee_id) {
                        frm.set_value('employee', employee_id);
                        // Make the employee field read-only for non-authorized users
                        if (!can_edit) {
                            frm.set_df_property('employee', 'read_only', 1);
                        }
                    } else {
                        frappe.msgprint(__('No Employee record linked to your user account. Please contact HR.'));
                    }
                }
            });
        } else if (frm.doc.employee) {
            // If employee already exists, make it read-only for non-authorized users
            if (!can_edit) {
                frm.set_df_property('employee', 'read_only', 1);
            }
        }
    },

    // Optional: Also lock employee field when it's set/changed
    employee: function(frm) {
        const can_edit_roles = ['HR User', 'HR Manager', 'System Manager'];
        const can_edit = can_edit_roles.some(role => frappe.user.has_role(role));

        if (frm.doc.employee && !can_edit) {
            frm.set_df_property('employee', 'read_only', 1);
        }
    }
});

