            // التنسيق: قديم / جديد / وقت / إيميل المضيف
            const log_entry = `${old_st} / ${new_st} / ${now} / ${user_email}`;
            
            frm.set_value('status_history', 
                frm.doc.status_history ? frm.doc.status_history + ',' + log_entry : log_entry
            );
            
          //  console.log('✅ Added:', log_entry);
            frm.old_status = new_st;
        }
    }
});

