frappe.ui.form.on('Attendance Request', {
    onload(frm) {
        set_employee_from_user(frm);
        apply_role_readonly(frm);
    },

    refresh(frm) {
        apply_role_readonly(frm);
    },

    employee(frm) {
        fill_employee_info(frm);
        set_shift_work_hours(frm);
    },

    hourly_request(frm) {
        if (frm.doc.hourly_request) {
            frm.set_value('work_hours', 1);
        } else {
            set_shift_work_hours(frm);
        }
    }
});

function is_hr_user() {
    return frappe.user.has_role('HR User') || frappe.user.has_role('HR Manager');
}

function apply_role_readonly(frm) {
    const fields = [
        'employee',
        'employee_name',
        'department',
        'company',
        'designation'
    ];

    const read_only = is_hr_user() ? 0 : 1;

    fields.forEach(field => {
        frm.set_df_property(field, 'read_only', read_only);
    });

    frm.refresh_fields(fields);
}

function set_employee_from_user(frm) {
    if (!frm.is_new()) return;

    frappe.db.get_value(
        'Employee',
        { user_id: frappe.session.user },
        ['name', 'employee_name', 'department', 'company', 'designation', 'default_shift']
    ).then(r => {
        if (!r.message || !r.message.name) return;

        const emp = r.message;

        frm.set_value('employee', emp.name);
        frm.set_value('employee_name', emp.employee_name);
        frm.set_value('department', emp.department);
        frm.set_value('company', emp.company);
        frm.set_value('designation', emp.designation);

        set_shift_work_hours(frm);
        apply_role_readonly(frm);
    });
}

function fill_employee_info(frm) {
    if (!frm.doc.employee) return;

    frappe.db.get_value(
        'Employee',
        frm.doc.employee,
        ['employee_name', 'department', 'company', 'designation']
    ).then(r => {
        if (!r.message) return;

        const emp = r.message;

        frm.set_value('employee_name', emp.employee_name);
        frm.set_value('department', emp.department);
        frm.set_value('company', emp.company);
        frm.set_value('designation', emp.designation);
    });
}

function set_shift_work_hours(frm) {
    if (!frm.doc.employee || frm.doc.hourly_request) return;

    frappe.db.get_value('Employee', frm.doc.employee, 'default_shift')
        .then(r => {
            const shift = r.message && r.message.default_shift;
            if (!shift) return;

            frappe.db.get_value(
                'Shift Type',
                shift,
                ['start_time', 'end_time']
            ).then(res => {
                if (!res.message) return;

                const hours = get_hours_diff(res.message.start_time, res.message.end_time);
                frm.set_value('work_hours', hours);
            });
        });
}

function get_hours_diff(start, end) {
    if (!start || !end) return 0;

    const s = String(start).split(':');
    const e = String(end).split(':');

    let startMinutes = (parseInt(s[0] || 0) * 60) + parseInt(s[1] || 0);
    let endMinutes = (parseInt(e[0] || 0) * 60) + parseInt(e[1] || 0);

    if (endMinutes < startMinutes) {
        endMinutes += 24 * 60;
    }

    return (endMinutes - startMinutes) / 60;
}

frappe.ui.form.on('Employee', {
    status: function(frm) {
        // Check if there's a linked user
        if (!frm.doc.user_id) {
            return;
        }

        // Case 1: Status is "Active" - Enable the user
        if (frm.doc.status === "Active") {
            frappe.confirm(
                __('Employee status is changed to "Active". Do you want to enable the linked user account?'),
                function() {
                    // User clicked "Yes" - enable the user
                    frappe.call({
                        method: "frappe.client.set_value",
                        args: {
                            doctype: "User",
                            name: frm.doc.user_id,
                            fieldname: "enabled",
                            value: 1
                        },
                        callback: function(r) {
                            if (r.message && r.message.enabled === 1) {
                                frappe.show_alert({
                                    message: __("User {0} has been enabled", [frm.doc.user_id]),
                                    indicator: 'green'
                                }, 5);
                            }
                        }
                    });
                },
                function() {
                    // User clicked "No" - do nothing
                    frappe.show_alert({
                        message: __("User {0} remains unchanged", [frm.doc.user_id]),
                        indicator: 'orange'
                    }, 3);
                }
            );
        } 
        // Case 2: Status is anything other than "Active" - Disable the user
        else {
            frappe.confirm(
                __('Employee status is changed to "{0}". Do you want to disable the linked user account?', [frm.doc.status]),
                function() {
                    // User clicked "Yes" - disable the user
                    frappe.call({
                        method: "frappe.client.set_value",
                        args: {
                            doctype: "User",
                            name: frm.doc.user_id,
                            fieldname: "enabled",
                            value: 0
                        },
                        callback: function(r) {
                            if (r.message && r.message.enabled === 0) {
                                frappe.show_alert({
                                    message: __("User {0} has been disabled", [frm.doc.user_id]),
                                    indicator: 'red'
                                }, 5);
                            }
                        }
                    });
                },
                function() {
                    // User clicked "No" - do nothing
                    frappe.show_alert({
                        message: __("User {0} remains unchanged", [frm.doc.user_id]),
                        indicator: 'orange'
                    }, 3);
                }
            );
        }
    }
});

